import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  DirectionalLight,
  PointLight,
  Color
} from 'three/webgpu';
import {
  uv,
  texture,
  vec3,
  float,
  mix,
  smoothstep,
  positionLocal,
  normalLocal
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group: ThreeGroup,
    Mesh: ThreeMesh,
    PlaneGeometry: ThreePlaneGeometry,
    BoxGeometry: ThreeBoxGeometry,
    MeshBasicNodeMaterial: ThreeMeshBasicNodeMaterial,
    MeshStandardNodeMaterial: ThreeMeshStandardNodeMaterial,
    DirectionalLight: ThreeDirectionalLight,
    PointLight: ThreePointLight,
    Color: ThreeColor
  } = ctx.THREE;

  const root = new ThreeGroup();
  root.name = 'home-quote-panel';

  const timelines = [];
  const primitiveCleanups = [];
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];

  const trackGeometry = (geometry) => {
    ownedGeometries.push(geometry);
    return geometry;
  };

  const trackMaterial = (material) => {
    ownedMaterials.push(material);
    return material;
  };

  const backdropGeometry = trackGeometry(new ThreePlaneGeometry(7, 6, 1, 1));
  const backdropMaterial = trackMaterial(new ThreeMeshBasicNodeMaterial());
  const backdropV = smoothstep(float(0.0), float(1.0), uv().y);
  backdropMaterial.colorNode = mix(
    vec3('#0b0b10'),
    mix(vec3('#16161d'), vec3('#e8ecf2'), backdropV.mul(float(0.08))),
    backdropV.mul(float(0.72))
  );

  const backdrop = new ThreeMesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'quote-stage-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const panelGroup = new ThreeGroup();
  panelGroup.name = 'quote-depth-stack';
  panelGroup.position.set(0, 0, 0.08);
  root.add(panelGroup);

  const shadowGeometry = trackGeometry(new ThreePlaneGeometry(3.9, 2.35, 1, 1));
  const shadowMaterial = trackMaterial(new ThreeMeshBasicNodeMaterial({
    color: new ThreeColor('#0b0b10'),
    transparent: true,
    opacity: 0.52
  }));
  const shadow = new ThreeMesh(shadowGeometry, shadowMaterial);
  shadow.name = 'quote-contact-shadow';
  shadow.position.set(0.08, -0.1, -0.12);
  shadow.scale.set(1.04, 0.92, 1);
  panelGroup.add(shadow);

  const imageGeometry = trackGeometry(new ThreePlaneGeometry(3.35, 2.05, 64, 64));
  const imageMaterial = trackMaterial(new ThreeMeshStandardNodeMaterial({
    color: new ThreeColor('#16161d'),
    roughness: 0.58,
    metalness: 0.42
  }));
  imageMaterial.colorNode = vec3('#16161d');

  const imagePanel = new ThreeMesh(imageGeometry, imageMaterial);
  imagePanel.name = 'quote-parallax-image';
  imagePanel.position.z = 0.08;
  panelGroup.add(imagePanel);

  const depthGeometry = trackGeometry(new ThreePlaneGeometry(3.35, 2.05, 64, 64));
  const depthMaterial = trackMaterial(new ThreeMeshStandardNodeMaterial({
    color: new ThreeColor('#16161d'),
    roughness: 0.62,
    metalness: 0.48
  }));
  depthMaterial.colorNode = vec3('#16161d');

  const depthPanel = new ThreeMesh(depthGeometry, depthMaterial);
  depthPanel.name = 'quote-depth-layer';
  depthPanel.position.z = 0.015;
  depthPanel.scale.set(1.015, 1.015, 1);
  panelGroup.add(depthPanel);

  const frameMaterial = trackMaterial(new ThreeMeshStandardNodeMaterial({
    color: new ThreeColor('#e8ecf2'),
    roughness: 0.56,
    metalness: 0.5
  }));

  const frameDepth = 0.13;
  const frameThickness = 0.07;
  const framePieces = [
    [3.56, frameThickness, 0, 1.08],
    [3.56, frameThickness, 0, -1.08],
    [frameThickness, 2.22, -1.745, 0],
    [frameThickness, 2.22, 1.745, 0]
  ];

  for (let i = 0; i < framePieces.length; i += 1) {
    const [width, height, x, y] = framePieces[i];
    const geometry = trackGeometry(new ThreeBoxGeometry(width, height, frameDepth, 2, 2, 2));
    const piece = new ThreeMesh(geometry, frameMaterial);
    piece.name = `quote-machined-frame-${i}`;
    piece.position.set(x, y, 0.16);
    panelGroup.add(piece);
  }

  const accentGeometry = trackGeometry(new ThreeBoxGeometry(0.045, 1.45, 0.06, 2, 2, 2));
  const accentMaterial = trackMaterial(new ThreeMeshStandardNodeMaterial({
    color: new ThreeColor('#ff2a38'),
    emissive: new ThreeColor('#ff2a38'),
    emissiveIntensity: 1.15,
    roughness: 0.5,
    metalness: 0.35
  }));
  const accentBar = new ThreeMesh(accentGeometry, accentMaterial);
  accentBar.name = 'quote-signal-red-rim';
  accentBar.position.set(-1.67, 0.02, 0.25);
  panelGroup.add(accentBar);

  const key = new ThreeDirectionalLight(new ThreeColor('#e8ecf2'), 0.95);
  key.name = 'quote-key-light';
  key.position.set(2.8, 3.4, 4.5);
  root.add(key);

  const rim = new ThreePointLight(new ThreeColor('#ff2a38'), 0.72, 5.5, 2);
  rim.name = 'quote-accent-rim-light';
  rim.position.set(-2.4, 1.2, 1.8);
  root.add(rim);

  const fontItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of fontItems) {
    if (!item || typeof item.text !== 'string') continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'caption' ? '#e8ecf2' : '#e8ecf2',
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    textObject.position.set(-1.25, -0.78, 0.28);
    panelGroup.add(textObject);
  }

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  const depthMapUrl = config.depthMapUrl ?? config.intent?.visualSpec?.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTextures.push(tex);
      tex.colorSpace = 'srgb';
      imageMaterial.colorNode = texture(tex, uv());
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTexture) => {
      loadedTextures.push(depthTexture);
      const depthNode = texture(depthTexture, uv()).r;
      const displacement = depthNode.sub(float(0.5)).mul(float(0.18));

      imageMaterial.positionNode = positionLocal.add(normalLocal.mul(displacement));
      depthMaterial.positionNode = positionLocal.add(normalLocal.mul(displacement.mul(float(0.72))));
      imageMaterial.needsUpdate = true;
      depthMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    if (!primitive || !primitive.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](root, primitive.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
  }

  panelGroup.position.y = -0.4;
  panelGroup.scale.setScalar(0.96);

  const entrance = gsap.timeline({ paused: true });
  entrance
    .to(panelGroup.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out'
    })
    .to(panelGroup.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.34,
      ease: 'power4.out'
    }, '<0.42')
    .to(panelGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }, '<');
  timelines.push(entrance);
  entrance.play();

  const hoverRise = gsap.timeline({ paused: true });
  hoverRise.to(panelGroup.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });

  root.userData.handlers = {
    hover: (active = true) => {
      if (active) hoverRise.play();
      else hoverRise.reverse();
    },
    click: () => {
      const press = gsap.timeline();
      press
        .to(panelGroup.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.out'
        })
        .to(panelGroup.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.45,
          ease: 'back.out(2)'
        });
      timelines.push(press);
      ctx.emit('hub-home.select', { node: root });
    }
  };

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }
    for (const cleanup of primitiveCleanups) cleanup();
    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();
    for (const textureResource of loadedTextures) textureResource.dispose?.();
  };

  return root;
}
